style.css:
@-moz-document domain("roblox.com") {
/* General dark background */
    body, html {
        background-color: #1a1a1a !important;
        color: #ffffff !important;
    }

    /* Neon pink top navigation bar */
    .navbar, .navigation-container {
        background-color: #ff0080 !important;
    }

    /* Buttons - neon pink with white text */
    button, .btn-primary, .btn-control-md, .btn-secondary-md {
        background-color: #ff3399 !important;
        color: #ffffff !important;
        border: none !important;
    }

    /* Links - neon blue */
    a {
        color: #00ffff !important;
    }

    /* Hide ads */
    .ads-container, .ad, .ad-container, .skyscraper {
        display: none !important;
    }

    /* Button hover effect */
    button:hover {
        background-color: #ff66cc !important;
        transform: scale(1.05);
        transition: all 0.2s ease-in-out;
    }

    /* Avatar Editor section */
    .avatar-editor-section, .avatar-editor {
        background-color: #262626 !important;
        border-radius: 10px;
        padding: 10px;
    }

    /* Custom scroll bar */
    ::-webkit-scrollbar {
        width: 10px;
    }

    ::-webkit-scrollbar-track {
        background: #1a1a1a;
    }

    ::-webkit-scrollbar-thumb {
        background: #ff66cc;
        border-radius: 5px;
    }
}
